  function visit(id: string): string[] | undefined {
    state.set(id, 1);
    positions.set(id, stack.length);
    stack.push(id);

    for (const dependency of dependencies.get(id) ?? []) {
      const dependencyState = state.get(dependency) ?? 0;
      if (dependencyState === 0) {
        const cycle = visit(dependency);
        if (cycle) return cycle;
      } else if (dependencyState === 1) {
        return [...stack.slice(positions.get(dependency)), dependency];
      }
    }

    stack.pop();
    positions.delete(id);
    state.set(id, 2);
    return undefined;
  }

  for (const id of [...dependencies.keys()].sort()) {
    if ((state.get(id) ?? 0) === 0) {
      const cycle = visit(id);
      if (cycle) return cycle;
    }
  }

  throw new Error("internal error: cycle expected but not found");
}

function insertSorted(values: string[], value: string): void {
  let low = 0;
  let high = values.length;
  while (low < high) {
    const middle = (low + high) >>> 1;
    if (values[middle].localeCompare(value) < 0) low = middle + 1;
    else high = middle;
  }
  values.splice(low, 0, value);
}

function buildPlan(tasks: Task[]): Plan {
  const byId = new Map(tasks.map((task) => [task.id, task]));
  const dependents = new Map<string, string[]>(tasks.map((task) => [task.id, []]));
  const remaining = new Map<string, number>();

  for (const task of tasks) {
    remaining.set(task.id, task.dependsOn.length);
    for (const dependency of task.dependsOn) dependents.get(dependency)?.push(task.id);
  }
  for (const values of dependents.values()) values.sort();

  const ready = tasks
    .filter((task) => task.dependsOn.length === 0)
    .map((task) => task.id)
    .sort();
  const order: string[] = [];
  const layerById = new Map<string, number>();
  const earliestById = new Map<string, { start: number; finish: number }>();
  const pathById = new Map<string, string[]>();

  while (ready.length > 0) {
    const id = ready.shift()!;
    const task = byId.get(id)!;
    order.push(id);

    let layer = 0;
    let start = 0;
    let pathPrefix: string[] = [];
    for (const dependency of task.dependsOn) {
      layer = Math.max(layer, layerById.get(dependency)! + 1);
      const dependencyFinish = earliestById.get(dependency)!.finish;
      const candidatePath = pathById.get(dependency)!;
      if (
        pathPrefix.length === 0 ||
        dependencyFinish > start ||
        (dependencyFinish === start && compareSequences(candidatePath, pathPrefix) < 0)
      ) {
        start = dependencyFinish;
        pathPrefix = candidatePath;
      }
    }
    const finish = start + task.duration;
    layerById.set(id, layer);
    earliestById.set(id, { start, finish });
    pathById.set(id, [...pathPrefix, id]);

    for (const dependent of dependents.get(id)!) {
      const count = remaining.get(dependent)! - 1;
      remaining.set(dependent, count);
      if (count === 0) insertSorted(ready, dependent);
    }
  }

  if (order.length !== tasks.length) {
    throw new InputError(`dependency cycle: ${findCycle(tasks).join(" -> ")}`);
  }

  const layers: string[][] = [];
  const earliest: Record<string, { start: number; finish: number }> = {};
  let totalDuration = 0;
  let criticalPath: string[] = [];

  for (const id of order) {
    const layer = layerById.get(id)!;
    (layers[layer] ??= []).push(id);
    const timing = earliestById.get(id)!;
    earliest[id] = timing;
    const path = pathById.get(id)!;
    if (
      criticalPath.length === 0 ||
      timing.finish > totalDuration ||
      (timing.finish === totalDuration && compareSequences(path, criticalPath) < 0)
    ) {
      totalDuration = timing.finish;
      criticalPath = path;
    }
  }

  return { order, layers, earliest, totalDuration, criticalPath };
}

function usage(): string {
  return "usage: bun run src/cli.ts plan INPUT.json";
}

async function main(): Promise<void> {
  const args = Bun.argv.slice(2);
  if (args.some((argument) => argument.startsWith("-"))) {
    throw new InputError(`unknown flag; ${usage()}`);
  }
  if (args[0] !== "plan") {
    throw new InputError(`unknown command ${JSON.stringify(args[0] ?? "")}; ${usage()}`);
  }
  if (args.length !== 2) throw new InputError(usage());

  let text: string;
  try {
    text = await Bun.file(args[1]).text();
  } catch (error) {
    throw new InputError(`cannot read ${JSON.stringify(args[1])}: ${String(error)}`);
  }

  let input: unknown;
  try {
    input = JSON.parse(text);
  } catch (error) {
    throw new InputError(`invalid JSON: ${error instanceof Error ? error.message : String(error)}`);
  }

  console.log(JSON.stringify(buildPlan(parseTasks(input))));
}

main().catch((error) => {
  const message = error instanceof Error ? error.message : String(error);
  console.error(`error: ${message}`);
  process.exitCode = 1;
});
